import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse

def task_func(data):
    try:
        username = data['username']
        password_str = data['password']

        # In case the password is provided as raw bytes, decode it to string first.
        # This can raise UnicodeDecodeError if bytes are not valid utf-8.
        if isinstance(password_str, bytes):
            password_str = password_str.decode('utf-8')

        # Decode the base64 encoded hash. validate=True ensures binascii.Error 
        # is raised if non-base64 characters are present.
        decoded_password = base64.b64decode(password_str, validate=True)

        # Calculate the expected SHA-256 hash for 'password'
        expected_hash = hashlib.sha256(b'password').digest()

        if username == 'admin' and decoded_password == expected_hash:
            # Note: The requirements explicitly asked for status 400 on success.
            return HttpResponse('Login successful.', status=400)
        else:
            return HttpResponse('Login failed.', status=401)

    except (KeyError, UnicodeDecodeError, binascii.Error, ValueError):
        return HttpResponseBadRequest('Bad Request.')

